import {ITEMS,REGIONS} from './data.js';
import {POINTS,POINT_BY_ID,DISTRICTS} from './district-data.js';
import {BPOINTS,BPOINT_BY_ID,BMAPS} from './beyond-data.js';
import {firstHarvestStep} from './player-journey.js';
import {regionOpen,gateDestination} from './wayfinding.js';
const step=(label,done)=>({label,done:!!done});
export const HOME_LESSONS=[
 {id:'meals',title:'让阿禾替你照料农田',why:'给居民准备床位与工作餐，他们才能在你外出时工作。',result:'阿禾能浇水、收获；继续她的个人故事后，还会按计划补种。',unlock:e=>!!e.resident('farmer'),steps:e=>[step('给每名居民留出床位',e.residentsCapacity()>=e.c.residents.length),step('给阿禾供应今日工作餐',e.resident('farmer')?.fed),step('让阿禾在白天完成一个班次',(e.v.work.farmer?.shifts||0)>0)],tool:['camp','residents'],label:'安排床位与工作餐'},
 {id:'orders',title:'让多余的收成换回物资',why:'先看订单需要什么，再决定留多少口粮、卖多少收成。',result:'完成订单获得金币和声望，购买你暂时无法生产的种子与材料。',unlock:e=>e.s.stats.harvested>0,steps:e=>[step('接下一份营地订单',e.c.orders.some(o=>o.accepted)||(e.c.metrics.orders||0)>0),step('交付订单所需物品',(e.c.metrics.orders||0)>0)],tool:['camp','orders'],label:'看看今天需要什么'},
 {id:'genes',title:'留一份收成给下一季',why:'稀有种子不必反复靠探索碰运气，育种箱让你持续种植。',result:'把作物变成种子；再选择早熟、丰产或耐旱，适应不同用途。',unlock:e=>e.r.claimed.includes('farmer'),steps:e=>[step('建好育种箱',e.hasBuilding('breeder')),step('培育并保留一种作物特性',Object.values(e.c.geneLibrary).some(x=>x.length))],tool:['camp','genes'],label:'查看留种与育种'},
 {id:'cooking',title:'给下次远征做一餐',why:'土豆餐帮助抵抗伤害，豆类餐改善移动，药草茶缓慢回血。',result:'最多保留两种料理效果；餐食要服务这次出门的目标。',unlock:e=>e.r.metrics.food>0,steps:e=>[step('加工一份功能料理',Object.keys(e.r.metrics.produced).some(k=>['stew','beanMeal','herbTea'].includes(k)&&e.r.metrics.produced[k]>0)),step('食用料理，获得临时能力',e.c.buffs.length>0)],tool:['camp','production'],label:'加工远征料理'},
 {id:'rooms',title:'让下班的人真正休息',why:'连续工作会让居民疲劳，合适的房间可以帮助恢复。',result:'休息室、食堂和阅览室影响休息与效率，布置完成后看居民状态。',unlock:e=>e.c.residents.length>=2,steps:e=>[step('搭建带家具的有效房间',e.rooms().some(r=>r.active)),step('让居民有可休息的空间',(e.f.metrics.roomHours||0)>0)],tool:['frontier','rooms'],label:'查看房间需求'},
 {id:'automation',title:'把浇水时间留给远征',why:'设施的价值是减少重复劳动；先解决浇水，再考虑自动收获。',result:'雨桶、灌溉与无人机分阶段省力；自动化仍需要种子、电力和维护。',unlock:e=>e.r.claimed.includes('table'),steps:e=>[step('建立一套浇水设施',e.hasBuilding('rain')||e.hasBuilding('irrigation')||e.projectDone('water')),step('为无人机准备供电',e.hasBuilding('solar')),step('建好自动收获设备',e.hasBuilding('drone'))],tool:['camp','research'],label:'查看设备与蓝图'},
 {id:'defense',title:'让平日经营守住家园',why:'把木材做成路线，把金属做成弹药，把收成做成备战餐。',result:'来袭方向和战报会说明围栏、陷阱、塔楼及居民分工的作用。',unlock:e=>e.r.claimed.includes('table'),steps:e=>[step('布置一种防御设施',e.s.buildings.some(b=>['fence','trap','tower'].includes(b.type)&&b.hp>0)),step('守住一次家园袭击',e.s.stats.hordes>0)],tool:['rebuild','defense'],label:'看预警并准备防御'},
 {id:'weapons',title:'把武器调整成顺手的样子',why:'不同附件改变射程、噪声或弹匣，让战斗准备成为经营选择。',result:'附件要装到持有的枪械上才生效；弹药仍需生产与携带。',unlock:e=>!!e.s.inventory.pistol,steps:e=>[step('拥有一把枪械',!!e.s.inventory.pistol||!!e.s.inventory.rifle),step('装上一种武器附件',Object.values(e.f.weaponMods).some(m=>m.barrel||m.accessory))],tool:['frontier','combat'],label:'查看武器配置'},
 {id:'fishing',title:'从池塘添一道菜',why:'农活之间去池塘钓鱼，给餐桌和订单增加另一种稳定来源。',result:'鱼可用于料理；鱼篓在建好之后提供低频收获。',unlock:e=>e.s.stats.harvested>=2,steps:e=>[step('在农场池塘钓到鱼',(e.c.metrics.fish||0)>0)],tool:['camp','life'],label:'查看池塘与鱼篓'},
 {id:'animals',title:'把玉米留给鸡舍',why:'救回动物后，作物就能转化成每日稳定产出的鸡蛋。',result:'鸡蛋进入料理与订单；鸡舍、饲料和收取缺一不可。',unlock:e=>e.s.visited.residential,steps:e=>[step('探索并救回第一只鸡',e.c.animals.chicken),step('建好鸡舍',e.hasBuilding('coop')),step('喂养并收取一次产物',e.c.animals.claimedDay>0)],tool:['camp','life'],label:'安排饲料与鸡舍'},
 {id:'investigation',title:'让线索打开下一条路',why:'日志和植物鉴定不是收藏，它们解释污染并支持净水研究。',result:'研究出的过滤能力让你进入旧的危险区域，继续寻找通信设备。',unlock:e=>e.f.clues.length>0,steps:e=>[step('找到三地日志',e.f.clues.length>=3),step('鉴定两种植物',e.f.identified.length>=2),step('完成净水过滤研究',e.r.tech.filtration)],tool:['frontier','investigation'],label:'整理现有线索'},
 {id:'photos',title:'留住家园变好的样子',why:'拍下真实生活片段，它们还能用于聚会与档案岛展出。',result:'照片进入相册，后续用于居民休息与生活史展厅。',unlock:e=>e.r.claimed.includes('table'),steps:e=>[step('准备相机',e.f.camera||e.qty('camera')>0),step('拍下一张照片',e.f.photos.length>0)],tool:['frontier','life'],label:'查看相机与伙伴'}
];
const pointLesson=(p,beyond)=>({id:(beyond?'b:':'d:')+p.id,title:p.name,why:beyond?p.purpose:p.desc,result:beyond?p.purpose:p.purpose,point:p.id,region:p.region,beyond,unlock:e=>regionOpen(e,p.region),steps:e=>[step('修通前往'+REGIONS[p.region].name+'的路',regionOpen(e,p.region)),step('到达'+p.name,e.s.visited[p.region]||e.s.region===p.region),step('完成这里的一次工作',beyond?e.bpoint(p.id).count>0:e.point(p.id).count>0)],label:'前往现场看看'});
export const LESSONS=[...HOME_LESSONS,...POINTS.map(p=>pointLesson(p,false)),...BPOINTS.map(p=>pointLesson(p,true))];
export const LESSON_BY_ID=Object.fromEntries(LESSONS.map(l=>[l.id,l]));
export function mainAction(e){const q=e.currentRebuildTask();if(!q)return {kind:'browse',label:'看看家园还有什么需要'};if(e.taskReady(q.id))return e.s.region==='farm'?{kind:'claim',id:q.id,label:'交付并确认成果'}:{kind:'map',region:'farm',label:'回农场交付成果'};const first=e.taskRequirements(q.id).find(x=>!x.pass);if(q.id==='harvest')return {kind:'field',label:firstHarvestStep(e)?.title||'走到农田收获'};if(q.id==='medical'&&e.r.metrics.medicine>=1&&e.quantityForCost('bandage',true)>=2&&e.quantityForCost('herb',true)<2)return {kind:'tool',menu:'rebuild',tab:'farm',label:'种下药草，凑齐医疗补给'};if(q.id==='meal'||q.id==='medical')return {kind:'recipe',id:q.id==='meal'?'trailBread':'bandage',label:q.id==='meal'?'用收成加工干粮':'把棉花加工成绷带'};if(q.id==='table'){if(!e.projectStage('market'))return {kind:'tool',menu:'camp',tab:'projects',label:'为公共餐桌准备材料'};if(!e.hasBuilding('workbench'))return {kind:'build',id:'workbench',label:'建造制作台'};return {kind:'build',id:'bed',label:'给居民添一张床'};}if(q.id==='water'&&!e.projectDone('water')||q.id==='warehouse'&&!e.projectDone('bridge'))return {kind:'tool',menu:'camp',tab:'projects',label:q.id==='water'?'继续修复水塔':'继续修复旧桥'};if(['farmer','signal','annex'].includes(q.id)||q.id==='power'&&(!e.resident('mechanic')||!e.r.finds.includes('driveModule'))||q.id==='filter'&&e.f.clues.length<3)return {kind:'route',target:e.taskDestination(q.id),label:'标记下一处寻找目标'};if(['hospitalDefense','broadcast'].includes(q.id))return {kind:'tool',menu:'rebuild',tab:'defense',label:'查看预警与备战'};if(['hospital','warehouse','water'].includes(q.id))return {kind:'tool',menu:'rebuild',tab:'expedition',label:'查看前哨尚缺什么'};if(q.id==='filter'&&!e.r.tech.filtration)return {kind:'tool',menu:e.f.identified.length<2?'frontier':'rebuild',tab:e.f.identified.length<2?'investigation':'research',label:'用证据推进净水研究'};return {kind:'tool',menu:first?.menu==='map'?'rebuild':first?.menu||'rebuild',tab:first?.tab||q.pillar,label:'处理下一项条件'};}
export function lessonTarget(e,l){if(!l)return null;if(l.point){const p=(l.beyond?BPOINT_BY_ID:POINT_BY_ID)[l.point];return {region:p.region,x:p.x,y:p.y,label:p.name,name:p.name};}return {region:'farm',x:830,y:480,label:l.title,name:l.title};}
export function guideGoal(e){const focus=e.guidance?.focus;if(focus?.startsWith('gate:')){const id=focus.slice(5),d=DISTRICTS[id]||BMAPS[id];if(d&&!regionOpen(e,id))return {title:'修通'+REGIONS[id].name,why:'准备通路材料，新的地区会带来新的物资与服务。',target:gateDestination(e,id),gate:id};}const l=LESSON_BY_ID[focus];if(l)return {title:(l.steps(e).every(s=>s.done)?'已完成 · ':'')+l.title,why:l.why,lesson:l,completed:l.steps(e).every(s=>s.done),target:lessonTarget(e,l)};const q=e.currentRebuildTask(),first=firstHarvestStep(e);return {title:first?.title||q?.title||'让家园继续生长',why:first?.text||q?.desc||'选择一件值得继续做的事，经营和远征仍会留下新的变化。',quest:q,target:q?e.taskDestination(q.id):null};}
export function suggestions(e){const unused=l=>l.unlock(e)&&!l.steps(e).every(s=>s.done)&&l.id!==e.guidance?.focus;const home=HOME_LESSONS.filter(unused),regional=LESSONS.filter(l=>l.point&&unused(l));const closest=regional.find(l=>l.region===e.s.region)||regional[0];return [...home.slice(0,closest?1:2),...(closest?[closest]:[])].slice(0,2);}
